-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "deDE" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.druid.balance.Name"] = "Gleichgewicht"
L["rm.era.druid.balance.Description"] = "Gleichgewicht von Stufe 1 bis 60 und der Druiden-Standard vor den Talenten oder wenn keine andere integrierte Rotation passt. Sternenfeuer als Füller, sobald erlernt (davor Zorn; Sternenfeuer zuerst bei einem Proc von Anmut der Natur), Mondfeuer und Insektenschwarm auf Zielen, die lange genug leben, aufrechterhalten, solange Ihr Mana über 30 % liegt, Hurrikan, wenn drei oder mehr Gegner gegen Sie kämpfen, Feenfeuer in einer Gruppe, Spontanzauber in Bewegung, Nahkampf ohne Mana. In Katzen- oder Bärengestalt gibt sie stattdessen die Empfehlungen für Wilder Kampf. Erinnerungen: Mal der Wildnis, Dornen beim Solospiel, Omen der Klarsicht, Moonkingestalt, wenn Sie in keiner Gestalt sind, Anregen, Griff der Natur. Herabstufen von Sternenfeuer, Wucherwurzeln und Zielwahl bleiben Ihnen überlassen."
L["rm.era.druid.balance.icyveins.Name"] = "Gleichgewicht (Icy Veins)"
L["rm.era.druid.balance.icyveins.Description"] = "Die Schlachtzugsliste von Icy Veins für Realms mit dem Limit von 16 Schwächungszaubern, eine Alternative zur empfohlenen integrierten Gleichgewichtsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Nur Sternenfeuer, kein Mondfeuer und kein Insektenschwarm, Hurrikan, wenn drei oder mehr Gegner gegen Sie kämpfen, Zorn nur, bevor Sternenfeuer erlernt ist. Dieselben Erinnerungen wie die empfohlene integrierte Gleichgewicht-Rotation."
L["rm.era.druid.feral.Name"] = "Wilder Kampf"
L["rm.era.druid.feral.Description"] = "Wilder Kampf als Katze und Bär ab Stufe 10, wenn Wilder Kampf Ihr Haupttalentbaum ist; Ihre Gestalt entscheidet, welche Variante. Katze: Eröffner aus der Verstohlenheit, Feenfeuer (Tiergestalt) aufrechterhalten, Freizaubern für Schreddern genutzt, ein Finisher ab vier Combopunkten (Zerfetzen, bevor Wilder Biss erlernt ist, und bei langen Kämpfen außerhalb von Schlachtzügen, Wilder Biss unter 63 Energie), Krallenhieb außerhalb von Schlachtzügen, Schreddern von hinten oder Klaue, wenn das Ziel Sie angreift, und ein Powershift (erneut Katzengestalt), wenn Ihnen viel Energie fehlt, mit Ingrimm 5/5 und überschüssigem Mana. Bär: Wutanfall bei Wutmangel, Demoralisierendes Gebrüll gegen Gruppen und Elitegegner, außer der Ruf eines Kriegers ist aktiv, Prankenhieb gegen zwei oder mehr Gegner und bei überschüssiger Wut, sonst Feenfeuer (Tiergestalt). In Zauberergestalt: Gestaltwechsel. Erinnerungen: Zermalmen bei jedem Schlag, Tigerfuror vor einem Pull, Manueller Meuteverprügler, Anregen, Rasende Regeneration. Positionierung bleibt Ihnen überlassen."
L["rm.era.druid.feral.warcrafttavern.Name"] = "Wilder Kampf (Warcraft Tavern, Zerfetzen und Wilder Biss)"
L["rm.era.druid.feral.warcrafttavern.Description"] = "Die Powershifting-Liste von Warcraft Tavern, eine Alternative zur empfohlenen integrierten Rotation für Wilder Kampf, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Zerfetzen bei fünf Combopunkten, wann immer es fehlt, auch in Schlachtzügen, dann Wilder Biss ab vier Combopunkten unter 63 Energie, Schreddern von hinten, Powershift, wenn Ihnen viel Energie fehlt. Bär und Erinnerungen wie bei der empfohlenen integrierten Rotation für Wilder Kampf."
L["rm.era.druid.feral.warcrafttavern.casual.Name"] = "Wilder Kampf (Warcraft Tavern, ohne Powershifting)"
L["rm.era.druid.feral.warcrafttavern.casual.Description"] = "Die Liste von Warcraft Tavern ohne Powershifting, eine Alternative zur empfohlenen integrierten Rotation für Wilder Kampf, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Mit Schreddern (Klaue von vorn) bis fünf Combopunkte aufbauen, dann Zerfetzen auf ein Ziel, das lange genug lebt, Tigerfuror, Wilder Biss; sonst auf Energie warten. Bär und Erinnerungen wie bei der empfohlenen integrierten Rotation für Wilder Kampf."
L["rm.era.druid.feral.wowhead.Name"] = "Wilder Kampf (Wowhead, Schlachtzugsbär)"
L["rm.era.druid.feral.wowhead.Description"] = "Die Katze der empfohlenen integrierten Rotation für Wilder Kampf mit dem gut ausgerüsteten Schlachtzugsbären von Wowhead: Zermalmen bei jedem Schlag (Zermalmen per Tab-Wechsel auf Gruppen übernehmen Sie selbst), Prankenhieb nur mit 60 überschüssiger Wut, sonst Feenfeuer (Tiergestalt), kein Demoralisierendes Gebrüll und kein Wutanfall im Kampf. Eine Alternative zur empfohlenen integrierten Rotation für Wilder Kampf, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
L["rm.era.druid.restoration.Name"] = "Wiederherstellung"
L["rm.era.druid.restoration.Description"] = "Wiederherstellung ab Stufe 10, wenn Wiederherstellung Ihr Haupttalentbaum ist. Heilt Ihr aktuelles freundliches Ziel: Heilende Berührung nach Schnelligkeit der Natur, Rasche Heilung unter 40 % auf Ihrem eigenen HoT, Verjüngung und Nachwachsen fortlaufend aufrechterhalten, Nachwachsen als Hauptheilung mit Verbessertem Nachwachsen, Heilende Berührung im höchsten Rang unter 45 % oder bei einem Proc von Anmut der Natur, sonst Heilende Berührung Rang 4. Gegen einen Gegner: Mondfeuer, Insektenschwarm und Zorn. Still in Katzen- oder Bärengestalt. Erinnerungen: Mal der Wildnis, Omen der Klarsicht, Schnelligkeit der Natur, Gelassenheit, Anregen, Wiedergeburt, Entfernen von Giften und Flüchen. Wen Sie heilen, bleibt Ihnen überlassen."
L["rm.era.druid.restoration.warcrafttavern.Name"] = "Wiederherstellung (Warcraft Tavern)"
L["rm.era.druid.restoration.warcrafttavern.Description"] = "Die Schadensstufen von Warcraft Tavern, eine Alternative zur empfohlenen integrierten Wiederherstellungsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Auf Ihrem freundlichen Ziel, ohne HoT-Pflege bei geringem Schaden: Rasche Heilung unter 40 %, Nachwachsen Rang 5 unter 50 %, Verjüngung und Nachwachsen Rang 3 unter 75 %, Heilende Berührung im höchsten Rang bei einem Proc von Anmut der Natur, Heilende Berührung Rang 3 unter 90 %. Erinnerungen wie bei der empfohlenen integrierten Wiederherstellungsrotation."
L["rm.forever.druid.balance.Name"] = "Gleichgewicht"
L["rm.forever.druid.balance.Description"] = "Gleichgewicht von Stufe 1 bis 60 und der Standard für jeden Forever-Druiden, zu dem keine andere integrierte Rotation passt (Stufen 1–9, Zauberwirker ohne Talente, Wiederherstellung beim Solospiel). Zieht mit Zorn; in Bewegung erneuert sie Mondfeuer, Insektenschwarm und in einer Gruppe Feenfeuer. Hurrikan, wenn drei oder mehr Gegner gegen Sie kämpfen, dann Ihr eigenes Mondfeuer und Ihren Insektenschwarm, Sternenfeuer, solange Ladungen von Finsternis oder Freizaubern aktiv sind, und Zorn; wenn Sie sich Zorn nicht leisten können, lässt sie Sie im Nahkampf kämpfen. Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst, wie Sie sich heilen und ob sich ein DoT auf einem Ziel lohnt. Erinnerungen: Mal der Wildnis, Dornen beim Solospiel, Moonkingestalt, eine Verjüngung vor dem Pull beim Solospiel, Griff der Natur, wenn ein Gegner Sie angreift, Anregen, sobald es beim Solospiel im Kampf bereit ist. Gestaltwechsel, Kontrolleffekte, Baumrinde und Zielwahl bleiben Ihnen überlassen. Erstellt aus Beta-Leitfäden für Stufe 30; die Schritte für Stufe 31–60 folgen dem Klassendesign und sind ungetestet."
L["rm.forever.druid.balance.tavern.Name"] = "Gleichgewicht, Multi-DoT (Warcraft Tavern)"
L["rm.forever.druid.balance.tavern.Description"] = "Multi-DoT-Levelstil von Warcraft Tavern, eine Alternative zur empfohlenen integrierten Gleichgewichtsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Zieht mit Zorn, hält Ihr Mondfeuer und Ihren Insektenschwarm auf dem Ziel, wurzelt es mit Wucherwurzeln fest, sobald beide wirken und ein weiterer Gegner gegen Sie kämpft, dann Zorn. Kein Sternenfeuer (der Build verzichtet auf Finsternis). Der Wechsel zum nächsten Gegner bleibt Ihnen überlassen. Erinnerungen: Mal der Wildnis, Dornen beim Solospiel."
L["rm.forever.druid.feral.Name"] = "Wilder Kampf, Katze und Bär"
L["rm.forever.druid.feral.Description"] = "Katze und Bär in einer integrierten Rotation, gewählt nach Ihrer Gestalt; sie übernimmt, sobald Wilder Kampf Ihr Haupttalentbaum ist (oder 11 Punkte hat) oder Sie in Katzen- oder Bärengestalt wechseln. Katze: Verheeren oder Schreddern aus Schleichen, Feenfeuer, Zerfetzen bei vier Combopunkten, Wilder Biss, sobald Zerfetzen wirkt, Krallenhieb, dann Schreddern, wenn das Ziel Ihnen nicht zugewandt ist (sonst Klaue). Bär: Feenfeuer und Wilde Attacke auf Distanz, Demoralisierendes Gebrüll in einer Gruppe oder gegen zwei Gegner, Urtümlicher Biss, Prankenhieb gegen drei oder mehr, Aufschlitzen, Prankenhieb. In Zauberergestalt schlägt sie Katzengestalt vor (Bärengestalt, bevor Sie Katzengestalt haben). Erinnerungen: Zermalmen in Bärengestalt, wann immer Sie es sich leisten können, Wutanfall, Berserker bei großen Pulls oder gegen Elitegegner, Anregen beim Solospiel, Mal der Wildnis, Dornen. Gesundheit, Energie, Wut und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst über Powershifting, Rasende Regeneration und Selbstheilung. Spotten, Unterbrechungen und Positionierung bleiben Ihnen überlassen."
L["rm.forever.druid.restoration.Name"] = "Wiederherstellung"
L["rm.forever.druid.restoration.Description"] = "Gruppenheilung nach Warcraft Tavern, sobald Wiederherstellung Ihr Haupttalentbaum mit 11 Punkten ist. Heilt Ihr aktuelles freundliches Ziel: Rasche Heilung auf ein Ziel mit Ihrem HoT, Wildwuchs, Nachwachsen und Verjüngung, wenn sie fehlen, Heilende Berührung. Gesundheit und Mana sind für Addons unter Forever verborgen, daher ist das Ziel, das Sie wählen, der einzige Hinweis darauf, wer Heilung braucht. Gegen ein feindliches Ziel: Mondfeuer, Insektenschwarm, Zorn. Erinnerungen: Anregen im Kampf, Schnelligkeit der Natur auf ein freundliches Ziel im Kampf, Fluch aufheben und Vergiftung aufheben, Mal der Wildnis; Gelassenheit bleibt Ihnen überlassen. Wen Sie heilen und den Zauberrang wählen Sie; Wiederherstellung beim Solospiel nutzt die integrierte Gleichgewichtsrotation."
L["rm.forever.druid.restoration.icyveins.Name"] = "Wiederherstellung, HoTs zuerst (Icy Veins)"
L["rm.forever.druid.restoration.icyveins.Description"] = "HoT-zuerst-Heilung nach Icy Veins, eine Alternative zur empfohlenen integrierten Wiederherstellungsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Auf Ihrem freundlichen Ziel: Verjüngung, dann Nachwachsen, wenn es fehlt, Heilende Berührung nur, wenn beide HoTs wirken, Rasche Heilung auf ein Ziel mit HoT, dann Wildwuchs (Gesundheit ist unter Forever verborgen, daher entscheidet das Ziel, das Sie wählen, wer geheilt wird). Anregen bei Abklingzeit-Ende. Ansonsten dieselben Erinnerungen und dieselbe Liste für feindliche Ziele wie die integrierte Wiederherstellungsrotation."
L["rm.mop.druid.balance.Name"] = "Empfohlen"
L["rm.mop.druid.balance.Description"] = "Empfohlen für Gleichgewicht ab Stufe 10, nach der Liste von Wowhead für Phase 5 und Simulation. Hält Mondfeuer und Sonnenfeuer aufrecht und erneuert sie in der passenden Finsternis, wirkt Sternenregen in Mondfinsternis, Sternensog bei Sternschnuppen und bei Abklingzeit-Ende, Hurrikan in Sonnenfinsternis oder Astralsturm in Mondfinsternis ab fünf Gegnern, Sternenfeuer in und nach Mondfinsternis und Zorn in und nach Sonnenfinsternis. Rotation Master kann die Finsternisenergie nicht auslesen, daher wirkt sie zwischen den Finsternissen weiter Sternenfeuer, wenn Sternenfeuer einer Ihrer letzten drei Zauber war, sonst Zorn. Erinnerungen: Mal der Wildnis, Mondkingestalt, Inkarnation zu Beginn einer Finsternis und Himmlische Ausrichtung an ihrem Ende (gegen Elitegegner oder bei langen Kämpfen), Wache der Natur, Naturgewalt, Schnelligkeit der Natur für Traum des Cenarius, Anregen, Sonnenstrahl, Baumrinde und Erneuerung bei niedriger Gesundheit. Das Platzieren von Wildpilz bleibt manuell; die Erinnerung an Detonieren ist standardmäßig deaktiviert. Sie pausiert, während Sie wirken, reisen, in Katzen- oder Bärengestalt sind oder keinen Gegner im Ziel haben."
L["rm.mop.druid.feral.Name"] = "Empfohlen"
L["rm.mop.druid.feral.Description"] = "Empfohlen für Wildheit ab Stufe 10, nach Simulation und der Liste von Wowhead für Phase 5. Versetzt Sie in Katzengestalt, eröffnet aus Schleichen mit Wildem Brüllen und Verheeren, hält Wildes Brüllen aufrecht, nutzt Schnelligkeit des Raubtiers für eine Heilende Berührung bei vier oder fünf Combopunkten mit Traum des Cenarius, Zerfetzen bei fünf Punkten (Wilder Biss erneuert es unter 25 % Gesundheit), Wilder Biss bei fünf Punkten, solange Zerfetzen und Wildes Brüllen beide noch sechs Sekunden haben, Krallenhieb, Hauen bei Freizaubern, Schreddern bei Freizaubern oder Berserker, wenn das Ziel Sie nicht angreift (Rotation Master kann nicht erkennen, ob Sie hinter ihm stehen), und Zerfleischen; Hauen und Prankenhieb ab vier Gegnern. In Bärengestalt gibt sie eine kurze Tankliste. Erinnerungen: Tigerfuror unter 35 Energie, Berserker damit gegen Elitegegner oder bei langen Kämpfen, Inkarnation, Naturgewalt, Wache der Natur, Schädelstoß, Überlebensinstinkte und Baumrinde bei niedriger Gesundheit, Mal der Wildnis. Bären- und Zorn-Weaving sowie Herz der Wildnis bleiben manuell."
L["rm.mop.druid.feral.icyveins.Name"] = "Wilder Biss nur in der Hinrichtungsphase (Icy Veins)"
L["rm.mop.druid.feral.icyveins.Description"] = "Die Wildheit-Reihenfolge von Icy Veins (die Biss-Regel von Wowhead stimmt überein), eine Alternative zur empfohlenen integrierten Wildheit-Rotation: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Dieselbe Eröffnung, dasselbe Wilde Brüllen, dieselbe Heilende Berührung und derselbe Flächenschaden, aber Combopunkte gehen über 25 % Gesundheit des Ziels nur in Zerfetzen und Wildes Brüllen: Wilder Biss erneuert Zerfetzen nur in der Hinrichtungsphase (oder gibt fünf Punkte aus, bevor Sie Zerfetzen erlernen). Krallenhieb wird bei zwei Sekunden erneuert, Hauen nur bei Freizaubern, und Berserker wartet auf 90 Energie, wenn Tigerfuror noch mindestens 15 Sekunden entfernt ist."
L["rm.mop.druid.guardian.Name"] = "Empfohlen"
L["rm.mop.druid.guardian.Description"] = "Empfohlen für Wächter-Tanks ab Stufe 10, nach Simulation und der Liste von Wowhead für Phase 5. Versetzt Sie in Bärengestalt, zieht mit Feenfeuer aus der Distanz oder mit Zerfleischen, hält Kampfesmüdigkeit mit Hauen und Rüstungsschwächung mit Feenfeuer auf Elitegegnern aufrecht, nutzt eine Heilende Berührung durch Traum des Cenarius bei Verletzung, Zerfleischen bei Abklingzeit-Ende, Hauen und Prankenhieb ab drei Gegnern, dann Aufschlitzen, Hauen und Feenfeuer. In Katzengestalt (Herz der Wildnis) gibt sie eine kurze Schadensliste. Erinnerungen: Wilde Verteidigung, wann immer sie fehlt, Wutanfall für Wut, Rasende Regeneration bei niedriger Gesundheit oder maximaler Wut, Zermalmen über 90 Wut oder bei Mit Klauen und Zähnen, Baumrinde, während das Ziel Sie angreift, Überlebensinstinkte bei niedriger Gesundheit, Berserker und Inkarnation gegen zwei Gegner oder einen Boss, Naturgewalt, Wache der Natur, Cenarischer Zauberschutz, Schädelstoß, Mal der Wildnis. Spotten und Ursocs Macht bleiben manuell (beide Erinnerungen sind standardmäßig deaktiviert)."
L["rm.mop.druid.restoration.Name"] = "Empfohlen"
L["rm.mop.druid.restoration.Description"] = "Empfohlen für Wiederherstellung ab Stufe 10, nach der Gruppenheilung von Wowhead für Phase 5. Heilt Ihr aktuelles freundliches Ziel oder Sie selbst ohne Ziel; wen Sie heilen, entscheiden Sie. Rasche Heilung auf ein Ziel mit Ihrem HoT, wenn es wenig Gesundheit hat, wenn Harmonie ausgelaufen ist oder als Vorbereitung auf Wildwuchs mit Seele des Waldes; Wildwuchs, wenn drei Personen in der Nähe verletzt sind; sofortige Heilende Berührung bei Schnelligkeit der Natur; Nachwachsen bei Freizaubern oder auf ein sterbendes Ziel; Verjüngung; dann Heilende Berührung und Pflege im Stillstand. Ein angreifbares Ziel erhält Mondfeuer und Zorn. Erinnerungen: Stapel von Blühendes Leben und Eisenborke auf Ihrem Fokus (legen Sie den Tank als Fokus fest), Wildpilz: Erblühen bei Gruppenschaden, Naturgewalt, Inkarnation, Wache der Natur, Schnelligkeit der Natur, Anregen, Heilung der Natur, Cenarischer Zauberschutz, Baumrinde, Mal der Wildnis. Erinnerungen an das Platzieren von Wildpilz, Gelassenheit und Genesis sind standardmäßig deaktiviert."
L["rm.mop.druid.restoration.wowhead.Name"] = "Tankheilung (Wowhead)"
L["rm.mop.druid.restoration.wowhead.Description"] = "Die Einzelziel-Tankheilung von Wowhead, eine Alternative zur empfohlenen integrierten Wiederherstellungsrotation, wenn Sie dem Tank zugewiesen sind: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Behalten Sie den Tank im Ziel: Sie hält drei Blühendes Leben und Verjüngung auf ihm, nutzt Nachwachsen bei hohem Schaden, Pflege bei leichtem Schaden, Heilende Berührung, sobald Blühendes Leben und Verjüngung laufen und der Tank unter der Hälfte ist, und Rasche Heilung, um ihn aufgefüllt zu halten. Dieselben Erinnerungen wie die empfohlene integrierte Rotation."
L["rm.mop.druid.unspecialized.Name"] = "Vor einer Spezialisierung"
L["rm.mop.druid.unspecialized.Description"] = "Für Stufe 1 bis 9 oder jeden Druiden, der noch keine Spezialisierung gewählt hat; die integrierten Rotationen der Spezialisierungen übernehmen, sobald Sie eine wählen. In Katzengestalt hält sie Krallenhieb aufrecht, gibt fünf Combopunkte (oder zwei auf ein sterbendes Ziel) für Wilden Biss aus und baut mit Zerfleischen auf; in Bärengestalt nutzt sie Zerfleischen und Zermalmen. Sonst zieht sie mit Zorn, hält Mondfeuer auf Zielen, die lange genug leben, wirkt Zorn (Mondfeuer in Bewegung) und schlägt Verjüngung auf Ihnen selbst vor, wenn Sie unter halber Gesundheit und allein sind. Sie pausiert, während Sie wirken, reisen oder keinen Gegner im Ziel haben."
L["rm.retail.druid.balance.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.druid.balance.Description"] = "Empfohlen für Gleichgewicht. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Himmlische Ausrichtung (oder Inkarnation) im Kampf, Sonnenstrahl bei einem unterbrechbaren Zauber, Mondkingestalt und Mal der Wildnis zwischen den Kämpfen sowie Baumrinde und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Sonnenstrahl nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz von Baumrinde Ihnen überlassen."
L["rm.retail.druid.balance.guide.Name"] = "Referenz (Icy Veins, SimulationCraft und Wowhead)"
L["rm.retail.druid.balance.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität der Leitfäden für Gleichgewicht. Ihre DoTs, Finsternis und Procs sind im Kampf in Midnight für Addons verborgen, daher kann sie dort nicht laufen; lesen Sie sie, oder duplizieren Sie sie, um damit zu experimentieren. Astrale Macht ist unter Retail verborgen, daher wirkt Sternensog zu seinen Kosten statt vor dem Maximum. Zieht mit Mondkingestalt und Zorn. Sonnenfeuer und Mondfeuer, wenn sie fehlen oder bald auslaufen; Finsternis, wenn keine aktiv ist (Mondfinsternis gegen drei oder mehr Gegner, sonst Sonnenfinsternis); Sternenregen bei Schuss des Sternwebers, Den Kosmos berühren oder gegen Gruppen; Sternensog bei Kette des Sternwebers oder Den Kosmos berühren; Neumond, Halbmond und Vollmond; Wildpilz während einer Finsternis; Sternensog, wann immer Sie es sich leisten können; Sternenfeuer während einer Mondfinsternis oder gegen Gruppen, sonst Zorn. Erinnerungen: Himmlische Ausrichtung oder Inkarnation, Zorn der Elune und Naturgewalt vor einer Finsternis, Konvokation während Himmlischer Ausrichtung, Sonnenstrahl, dazu die Erinnerungen an Hilfsfähigkeiten."
L["rm.retail.druid.feral.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.druid.feral.Description"] = "Empfohlen für Wildheit. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Berserker (oder Inkarnation) im Kampf, Schädelstoß bei einem unterbrechbaren Zauber, Überlebensinstinkte, Baumrinde und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind, sowie Katzengestalt und Mal der Wildnis zwischen den Kämpfen. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet die Unterbrechung nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz der Defensivfähigkeiten Ihnen überlassen."
L["rm.retail.druid.feral.guide.Name"] = "Referenz (Icy Veins und SimulationCraft)"
L["rm.retail.druid.feral.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität der Leitfäden für Wildheit. Blutungen und Procs sind im Kampf in Midnight verborgen (Combopunkte nicht), daher kann sie dort nicht laufen; Energie ist unter Retail verborgen. Eröffnet mit Katzengestalt, Schleichen und Krallenhieb. Zubeißen; Wilder Biss bei Gelüst des Eliteraubtiers; bei fünf Combopunkten Urzorn gegen zwei oder mehr Gegner, Zerfetzen, wenn es fehlt oder in seinen letzten Sekunden ist, sonst Wilder Biss, wobei auf Energie gewartet statt über fünf Punkte hinaus aufgebaut wird; unter fünf Krallenhieb, wenn er fehlt oder bald ausläuft, Mondfeuer mit Mondinspiration, Prankenhieb gegen drei oder mehr Gegner, Schreddern. Erinnerungen: Tigerfuror, wann immer er im Kampf bereit ist, Berserker oder Inkarnation sowie Wilde Raserei oder Tobende Raserei (bei zwei Punkten oder weniger) während Tigerfuror, Konvokation während Tigerfuror und Berserker bei aktivem Zerfetzen, Schädelstoß, Überlebensinstinkte, dazu die Erinnerungen an Hilfsfähigkeiten. Snapshotting bleibt Ihnen überlassen."
L["rm.retail.druid.guardian.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.druid.guardian.Description"] = "Empfohlen für Wächter. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; der Kampfassistent spielt nur auf Schaden. Daneben Erinnerungen an das, was er Ihnen überlässt: Berserker (oder Inkarnation) und Konvokation der Geister im Kampf, Eisenfell, Rasende Regeneration, Überlebensinstinkte, Baumrinde und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind, Schädelstoß bei einem unterbrechbaren Zauber sowie Bärengestalt und Mal der Wildnis zwischen den Kämpfen. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Schädelstoß nur dort auf, wo das Spiel sie anzeigt; Gesundheit und Wut sind unter Retail verborgen, daher bleibt der Einsatz der Defensivfähigkeiten Ihnen überlassen, und Eisenfell kann nicht auf eine Wutschwelle warten."
L["rm.retail.druid.guardian.guide.Name"] = "Referenz (Icy Veins und Wowhead)"
L["rm.retail.druid.guardian.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität der Leitfäden für Wächter. Schwächungszauber und Procs sind im Kampf in Midnight verborgen, daher kann sie dort nicht laufen; Wut und Gesundheit sind unter Retail verborgen, daher bleibt das Abladen von Wut mit Plätten und Zermalmen ab 80 Wut Ihnen überlassen. Hauen und Zerfleischen bei Abklingzeit-Ende, Blutmond gegen ein einzelnes Ziel, Mondfeuer, wenn es fehlt, oder bei Galaktischem Wächter, Prankenhieb. Erinnerungen, wann immer sie im Kampf bereit sind: Eisenfell, Rasende Regeneration, Überlebensinstinkte; Bärengestalt zwischen den Kämpfen; Berserker oder Inkarnation, Mondstrahl, Konvokation, Herz der Wildnis, Schädelstoß, dazu die Erinnerungen an Hilfsfähigkeiten."
L["rm.retail.druid.guardian.simc.Name"] = "Defensive Referenz (SimulationCraft)"
L["rm.retail.druid.guardian.simc.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Liste von SimulationCraft für Wächter, die Wut zuerst für Eisenfell ausgibt. Verborgene Kampfdaten verhindern, dass sie im Kampf in Midnight läuft, und Wut ist unter Retail verborgen, daher entfallen ihre Wutschwellen. Eisenfell während Berserker; Hauen, wenn es fehlt, bald ausläuft oder unter drei Stapeln liegt; Zermalmen bei Blutigem Fell; Hauen gegen drei oder mehr Gegner; Zerfleischen, solange Blutmond tickt; Blutmond; Zerfleischen; Hauen; Mondfeuer; Prankenhieb. Das Einweben von Katzengestalt lässt sie aus. Erinnerungen: Bärengestalt, Rasende Regeneration, Überlebensinstinkte, Berserker oder Inkarnation, Mondstrahl, Konvokation, Schädelstoß, dazu die Erinnerungen an Hilfsfähigkeiten."
L["rm.retail.druid.initial.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.druid.initial.Description"] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Druiden meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Druiden-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung."
L["rm.retail.druid.restoration.Name"] = "Blizzard-Kampfassistent mit Pflege"
L["rm.retail.druid.restoration.Description"] = "Empfohlen für Wiederherstellung. Mit einem anvisierten Gegner hebt sie den Vorschlag von Blizzards Kampfassistent hervor, Blizzards Schadensliste für Wiederherstellung in Katzen- oder Normalgestalt. Andernfalls schlägt sie die Erhaltungszauber nach Icy Veins auf Ihr freundliches Ziel (oder Sie selbst) vor: Blühendes Leben, Erblühen im Kampf, Rasche Heilung auf eine Verjüngung, Wildwuchs in einer Gruppe im Kampf, Nachwachsen bei Freizaubern oder fünf Stapeln Überfluss, Verjüngung, wenn sie fehlt. Gesundheit und Mana sind unter Retail verborgen, daher folgen diese dem Ziel, das Sie wählen, und nicht danach, wie verletzt jemand ist; Ihre Heilungen über Zeit sind im Kampf in Midnight verborgen, daher warten die Schritte, die sie lesen, dort. Wen Sie heilen, und jede Heil-Abklingzeit liegen bei Ihnen. Erinnerungen: Anregen, Baumrinde und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind, Mal der Wildnis zwischen den Kämpfen."
L["rm.sod.druid.balance.Name"] = "Gleichgewicht (SoD)"
L["rm.sod.druid.balance.Description"] = "Gleichgewicht in der Saison der Entdeckungen von Stufe 1 bis 60 und der Standard für jeden Druiden, zu dem keine andere integrierte Rotation der Saison der Entdeckungen passt. Sternensog, wann immer sein Stärkungszauber fehlt, Sonnenfeuer und Mondfeuer auf Zielen, die lange genug leben, Sternenfeuer nur, wenn Sternensog oder Mondfinsternis es verstärkt, Zorn als Füller, Hurrikan gegen sechs oder mehr Gegner (vier mit der Rune Orkanwinde), Insektenschwarm nur in Bewegung. Runen werden genutzt, sobald Sie sie gravieren. In Katzen- oder Bärengestalt gibt sie die Empfehlungen für Wilder Kampf. Erinnerungen: Moonkingestalt, Sternenregen, sofortige Heilende Berührung auf einen sterbenden Verbündeten, Entfernen von Flüchen und Giften, Wildwuchs bei einer verletzten Gruppe, Anregen. Das Verteilen von DoTs auf andere Ziele bleibt Ihnen überlassen."
L["rm.sod.druid.balance.icyveins.Name"] = "Gleichgewicht (SoD, Icy Veins)"
L["rm.sod.druid.balance.icyveins.Description"] = "Die Liste von Icy Veins für die Saison der Entdeckungen, eine Alternative zur empfohlenen integrierten Gleichgewichtsrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Sternensog bei Abklingzeit-Ende, Hurrikan gegen vier oder mehr Gegner (für Orkanwinde), Sternenfeuer, wenn Sternensog es verstärkt, Mondfeuer, Sonnenfeuer und Insektenschwarm alle aufrechterhalten, Zorn als Füller. Erinnerungen wie bei der empfohlenen integrierten Rotation."
L["rm.sod.druid.balance.wowhead.Name"] = "Gleichgewicht (SoD, Wowhead)"
L["rm.sod.druid.balance.wowhead.Description"] = "Die Liste von Wowhead für Phase 8, eine Alternative zur empfohlenen integrierten Gleichgewichtsrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Zorn zum Eröffnen, Sternensog bei Abklingzeit-Ende, Hurrikan gegen sechs oder mehr Gegner, Insektenschwarm nur in Bewegung, Sonnenfeuer und Mondfeuer aufrechterhalten, Zorn, solange Ihr Sonnenfeuer weniger als 5 Sekunden hat, wenn Feuer Elunes eingraviert ist, um es zu verlängern, Sternenfeuer bei Mondfinsternis, sonst Zorn. Erinnerungen wie bei der empfohlenen integrierten Rotation."
L["rm.sod.druid.feral.Name"] = "Wilder Kampf, Katze (SoD)"
L["rm.sod.druid.feral.Description"] = "Katze in der Saison der Entdeckungen, gewählt, wenn Wildes Brüllen graviert ist (oder Wilder Kampf ohne eine andere Beinrune Ihr Haupttalentbaum ist). Feenfeuer (Tiergestalt), wenn keines aktiv ist, Wildes Brüllen, Prankenhieb (Katze) gegen vier oder mehr Gegner, der Schwächungszauber von Zerfleischen, Freizaubern für Schreddern, Zerfetzen bei fünf Combopunkten, solange Wildes Brüllen noch 8 Sekunden hat, Krallenhieb, Schreddern von hinten oder Zerfleischen von vorn, Powershift mit Ingrimm 5/5, Erneuern von Feenfeuer zuletzt. In Bärengestalt gibt sie die Tank-Empfehlungen. Erinnerungen: Tigerfuror bei 60 Energie oder weniger, Berserker mit Tigerfuror, Zermalmen, Anregen. Positionierung bleibt Ihnen überlassen."
L["rm.sod.druid.restoration.Name"] = "Wiederherstellung (SoD)"
L["rm.sod.druid.restoration.Description"] = "Wiederherstellung in der Saison der Entdeckungen, gewählt, wenn Blühendes Leben graviert ist (oder Wiederherstellung ohne eine andere Beinrune Ihr Haupttalentbaum ist). Heilt Ihr aktuelles freundliches Ziel: sofortige Heilende Berührung nach Schnelligkeit der Natur oder Furor von Sturmgrimm, Wildwuchs, wenn zwei oder mehr Verbündete in der Nähe verletzt sind, Rasche Heilung auf Ihrem HoT für Erblühen oder unter 40 %, drei Stapel Blühendes Leben, erneuert, wenn noch eine Sekunde bleibt, Verjüngung, Nachwachsen unter 60 %, Pflege, Heilende Berührung Rang 4. Gegen einen Gegner: Sonnenfeuer, Mondfeuer, Zorn. Erinnerungen: Baum des Lebens und Überlebensinstinkte in schweren Momenten, Schnelligkeit der Natur, Gelassenheit, Anregen, Wiedergeburt, Wiederbelebung, Bannungen. Wen Sie heilen, bleibt Ihnen überlassen."
L["rm.sod.druid.tank.Name"] = "Bärentank (SoD)"
L["rm.sod.druid.tank.Description"] = "Bärentank in der Saison der Entdeckungen, gewählt, wenn Aufschlitzen graviert ist. Feenfeuer (Tiergestalt) oder Sonnenfeuer (Bär), um aus der Distanz zu ziehen, Aufschlitzen, bevor es ausläuft, Zerfleischen bei Abklingzeit-Ende, Aufschlitzen, Prankenhieb; gegen drei oder mehr Gegner Zerfleischen während Berserker und Prankenhieb. In Katzengestalt spielt sie die Katzenliste für das Offtanking; in Zauberergestalt wechselt sie in Bärengestalt. Erinnerungen: Zermalmen bei 30 Wut, Berserker, Überlebensinstinkte, Rasende Regeneration und Baumrinde bei niedriger Gesundheit, Wutanfall zwischen den Pulls, Demoralisierendes Gebrüll gegen Elitegegner. Spotten und Zielwahl bleiben Ihnen überlassen."
L["rm.sod.druid.tank.simulator.Name"] = "Bärentank (SoD, Katzen-Weaving nach Simulation)"
L["rm.sod.druid.tank.simulator.Description"] = "Standardmäßig deaktiviert; für Experten, deren Ausrüstung zusätzlich Wildes Brüllen gewährt. Das Katzen-Weaving von Simulation für Phase 7: Wechseln Sie vom Bären zur Katze, wenn Ihr Krallenhieb fehlt, halten Sie Wildes Brüllen und Krallenhieb aufrecht (Tigerfuror, Zerfleischen zum Aufbauen), kehren Sie dann zur Terrorbärengestalt zurück und spielen Sie die Tankliste. Erinnerungen wie bei der empfohlenen integrierten Tankrotation."
L["rm.tbc.druid.balance.Name"] = "Gleichgewicht"
L["rm.tbc.druid.balance.Description"] = "Gleichgewicht als Zauberwirker von Stufe 1 bis 70 und der Standard für jeden Druiden, zu dem keine andere integrierte Rotation passt. Zieht mit Sternenfeuer (Zorn vor Stufe 20), Insektenschwarm und Mondfeuer in Bewegung, Feenfeuer in einer Gruppe, Hurrikan für drei oder mehr Gegner, Mondfeuer, wenn es ausgelaufen ist und Sie 30 % Mana haben, Sternenfeuer bei Anmut der Natur, Zorn gegen ein Ziel im Nahkampf, dann Sternenfeuer (Zorn, bevor es erlernt ist). Keine Empfehlungen in Katzen-, Bären- oder Reisegestalt. Erinnerungen: Mal der Wildnis, Dornen beim Solospiel, Omen der Klarsicht, Mondkingestalt, Naturgewalt bei einem langen Kampf, Anregen bei wenig Mana."
L["rm.tbc.druid.feral.icyveins.Name"] = "Wilder Kampf (Icy Veins, Warcraft Tavern & Simulation)"
L["rm.tbc.druid.feral.icyveins.Description"] = "Katze und Bär für den Baum Wilder Kampf, je nach Ihrer Gestalt. Katze: Eröffner aus der Verstohlenheit (Anspringen, Verheeren oder Schreddern), Feenfeuer (Tiergestalt), Zerfetzen bei vier Combopunkten auf ein Ziel, das lange genug lebt, Wilder Biss zwischen Zerfetzen ohne Freizaubern, Zerfleischen aufrechterhalten, Schreddern von hinten oder Zerfleischen/Klaue, wenn das Ziel Sie angreift. Bär: Feenfeuer, Aufschlitzen erneuert, bevor es ausläuft, Demoralisierendes Gebrüll, außer ein Ruf eines Kriegers ist aktiv, Prankenhieb gegen Gruppen, Zerfleischen, fünfmal Aufschlitzen, Prankenhieb. In Zauberergestalt schlägt sie Katzen- (oder Bären-)gestalt vor. Erinnerungen: Mal, Dornen, Omen, Zermalmen bei überschüssiger Wut, Tigerfuror vor einem Pull, Rasende Regeneration. Powershifting ist ein optionaler Schritt, der deaktiviert beginnt (er benötigt ein Powershift-Makro)."
L["rm.tbc.druid.feral.wowhead.Name"] = "Wilder Kampf (Wowhead)"
L["rm.tbc.druid.feral.wowhead.Description"] = "Wilder Kampf nach Wowhead, eine Alternative zur empfohlenen integrierten Rotation für Wilden Kampf nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Zerfetzen, sobald es fehlt, bei vier Combopunkten und Wilder Biss nur auf ein Ziel kurz vor dem Tod (kein Bite-Weaving); Bären nutzen freie globale Abklingzeiten für Aufschlitzen vor Prankenhieb. Anregen, wenn einer Katze das Mana ausgeht. Ansonsten wie die Icy-Veins-Variante."
L["rm.tbc.druid.restoration.Name"] = "Wiederherstellung"
L["rm.tbc.druid.restoration.Description"] = "Heilung für den Baum Wiederherstellung auf Ihr freundliches Ziel (oder Sie selbst): Heilende Berührung nach Schnelligkeit der Natur, Rasche Heilung auf ein sterbendes Ziel mit Ihrer Verjüngung oder Ihrem Nachwachsen, drei rollierende Blühendes Leben im Kampf, Verjüngung und Nachwachsen, wenn sie fehlen, dann Nachwachsen im Baum des Lebens oder Heilende Berührung außerhalb davon. Ein feindliches Ziel erhält für das Solospiel Mondfeuer und Zorn. Erinnerungen: Mal, Omen, Baum des Lebens, Schnelligkeit der Natur, Gelassenheit, Anregen und Wiedergeburt. Wen Sie heilen und das Herabstufen von Rängen bleiben Ihnen überlassen."
